1	/**
2	 * no-duplicate-code — flags every block jscpd reports as copied from
3	 * elsewhere in the scanned roots, spanning the whole duplicated range so an
4	 * editor highlights exactly what was pasted.
5	 *
6	 * jscpd is a whole-tree scanner, so one scan per process serves every file:
7	 * the index is cached per `cwd` + options. An editor ESLint server keeps its
8	 * process alive across saves, so a rescan happens when the linted file, or
9	 * the twin of any clone reported in it, has an mtime newer than the cached
10	 * scan — that is how a just-removed clone stops being reported on BOTH sides
11	 * without a restart. A clone newly introduced by editing some other file is
12	 * seen once that file is linted; the file at hand was not part of it before.
13	 *
14	 * `roots` are directories: jscpd walks them itself and treats a glob as a
15	 * path that does not exist, scanning nothing, so a missing root is reported
16	 * instead of silently passing.
17	 */
18	import { statSync } from "node:fs";
19	import { relative, resolve } from "node:path";
20	import { resolveJscpdBin, runJscpd } from "./lib/jscpd/runner.mjs";
21	/** Below this much real code, a match is a shared dependency list with spillover, not duplicated logic. */
22	const MIN_CODE_LINES = 3;
23	const IMPORT_LINE = /^(import|export)\b[^;]*(from\s|["'])/;
24	const CONTINUATION_LINE = /^[\w$*{},\s]*(\}\s*from\s|["']|,)?[;,]?$/;
25	const scans = new Map();
26	const reportedUnavailable = new Set();
27	function cacheKey(cwd, options) {
28	    return `${cwd}\n${JSON.stringify(options)}`;
29	}
30	function scan(cwd, options) {
31	    const bin = resolveJscpdBin(cwd, options.jscpdBin);
32	    return runJscpd({
33	        cwd,
34	        bin,
35	        roots: options.roots ?? ["."],
36	        minTokens: options.minTokens ?? 50,
37	        minLines: options.minLines,
38	        mode: options.mode,
39	        ignore: options.ignore,
40	        formats: options.formats,
41	    });
42	}
43	function fileChangedSince(filename, startedAt) {
44	    try {
45	        return statSync(filename).mtimeMs > startedAt;
46	    }
47	    catch {
48	        return false;
49	    }
50	}
51	function isStale(entry, filename) {
52	    const startedAt = entry.startedAt ?? 0;
53	    const twins = (entry.byFile?.get(filename) ?? []).map((clone) => clone.twin.file);
54	    return [filename, ...twins].some((path) => fileChangedSince(path, startedAt));
55	}
56	function scanFor(cwd, options, filename) {
57	    const key = cacheKey(cwd, options);
58	    const cached = scans.get(key);
59	    if (cached && !isStale(cached, filename)) {
60	        return { key, entry: cached };
61	    }
62	    const entry = scan(cwd, options);
63	    scans.set(key, entry);
64	    return { key, entry };
65	}
66	function reportUnavailable(context, key, error) {
67	    if (reportedUnavailable.has(key)) {
68	        return;
69	    }
70	    reportedUnavailable.add(key);
71	    context.report({
72	        loc: { line: 1, column: 0 },
73	        messageId: "unavailable",
74	        data: { error },
75	    });
76	}
77	/** A line that carries no logic of its own: blank, a comment, or part of an import or export-from statement. */
78	function isDeclarationLine(line, inBlockComment) {
79	    const text = line.trim();
80	    if (inBlockComment) {
81	        return { declaration: true, inBlockComment: !text.includes("*/") };
82	    }
83	    if (text.startsWith("/*")) {
84	        return { declaration: true, inBlockComment: !text.includes("*/") };
85	    }
86	    return { declaration: carriesNoLogic(text), inBlockComment: false };
87	}
88	function carriesNoLogic(text) {
89	    const isComment = text.startsWith("//") || text.startsWith("*");
90	    return (text === "" ||
91	        isComment ||
92	        IMPORT_LINE.test(text) ||
93	        CONTINUATION_LINE.test(text));
94	}
95	/**
96	 * True when the clone carries almost no logic of its own: two modules
97	 * importing the same things is what sharing a library looks like, and the
98	 * only way to stop jscpd matching it is a barrel that hides where each
99	 * symbol comes from, which is a worse file to read. A match runs on past the
100	 * last import into whatever follows, so a couple of trailing lines are the
101	 * spillover rather than the duplication.
102	 */
103	function isDependencyList(sourceCode, clone) {
104	    const lines = sourceCode.lines.slice(clone.start.line - 1, clone.end.line);
105	    let inBlockComment = false;
106	    let codeLines = 0;
107	    for (const line of lines) {
108	        const verdict = isDeclarationLine(line, inBlockComment);
109	        inBlockComment = verdict.inBlockComment;
110	        codeLines += verdict.declaration ? 0 : 1;
111	    }
112	    return codeLines < MIN_CODE_LINES;
113	}
114	function reportClone(context, cwd, clone) {
115	    context.report({
116	        loc: { start: clone.start, end: clone.end },
117	        messageId: "duplicate",
118	        data: {
119	            lines: String(clone.lines),
120	            tokens: String(clone.tokens),
121	            twin: relative(cwd, clone.twin.file),
122	            twinStart: String(clone.twin.startLine),
123	            twinEnd: String(clone.twin.endLine),
124	        },
125	    });
126	}
127	export default {
128	    meta: {
129	        type: "suggestion",
130	        docs: {
