        outcome: {rejected: true, value: undefined},
        callOrder: ['onError', 'afterSession'],
        isError: true,
        message: expect.stringMatching(/\S/),
        hookGotOriginal: false,
        callerGotOriginal: true,
      },
      error: {
        outcome: {rejected: true, value: alreadyError},
        callOrder: ['onError', 'afterSession'],
        isError: true,
        message: 'rate limited',
        hookGotOriginal: true,
        callerGotOriginal: true,
      },
    });
  });
});

