1	/**
2	 * declare-near-use — declare variables close to their usage. A `const` bound
3	 * at the top of a block and first read a dozen statements later makes the
4	 * reader carry it the whole way down; declaring it right above its first use
5	 * keeps the value and its purpose on the same screen.
6	 *
7	 * What counts: a `const` / `let` declaration that is a direct child of a
8	 * `BlockStatement` or `Program`, whose first reference (init reference
9	 * excluded) lands in a sibling statement of the same list. When more than
10	 * `maxDistance` (default 5) statements separate the declaration from that
11	 * sibling, the declaration is reported. Skipped, because a later position
12	 * would change meaning or is not obviously better:
13	 *   - the first reference sits inside a nested block or function (a loop body,
14	 *     a callback, an `if` arm) — hoisting it into the branch is a judgment call;
15	 *   - references spread over two or more branching siblings (`if` / `switch` /
16	 *     `try`) — the declaration is shared state between arms;
17	 *   - `let` without an initialiser — deliberately declared for later assignment;
18	 *   - `var`, and exported Program-level declarations (an export is a reference).
19	 *
20	 * Detect-only: moving a declaration past side-effecting statements needs a
21	 * human to confirm nothing observes the old order.
22	 */
23	const BLOCK_PARENTS = new Set(["BlockStatement", "Program"]);
24	const BRANCHING = new Set(["IfStatement", "SwitchStatement", "TryStatement"]);
25	const NESTING = new Set([
26	    "BlockStatement",
27	    "FunctionDeclaration",
28	    "FunctionExpression",
29	    "ArrowFunctionExpression",
30	    "ClassBody",
31	    "StaticBlock",
32	]);
33	function isCandidate(node) {
34	    if (node.kind === "var" || !BLOCK_PARENTS.has(node.parent.type)) {
35	        return false;
36	    }
37	    return node.declarations.every((declarator) => declarator.init);
38	}
39	/**
40	 * Walks from a reference up to the statement list holding `declaration`,
41	 * noting whether a nested scope sits between the reference and that sibling.
42	 */
43	function locateReference(identifier, declaration) {
44	    const list = declaration.parent;
45	    let node = identifier;
46	    let nested = false;
47	    while (node.parent && node.parent !== list) {
48	        node = node.parent;
49	        nested = nested || NESTING.has(node.type);
50	    }
51	    return { statement: node, nested, name: identifier.name };
52	}
53	function usageSites(sourceCode, declaration) {
54	    return sourceCode
55	        .getDeclaredVariables(declaration)
56	        .flatMap((variable) => variable.references)
57	        .filter((reference) => !reference.init)
58	        .map((reference) => reference.identifier)
59	        .sort((a, b) => a.range[0] - b.range[0])
60	        .map((identifier) => locateReference(identifier, declaration))
61	        .filter((site) => site.statement !== declaration);
62	}
63	function spansBranches(sites) {
64	    const arms = new Set(sites
65	        .map((site) => site.statement)
66	        .filter((statement) => BRANCHING.has(statement.type)));
67	    return arms.size >= 2;
68	}
69	function statementDistance(declaration, statement) {
70	    const list = declaration.parent.body;
71	    return list.indexOf(statement) - list.indexOf(declaration) - 1;
72	}
73	export default {
74	    meta: {
75	        type: "suggestion",
76	        docs: {
77	            description: "Require a const/let declaration to sit within a few statements of its first use in the same block",
78	        },
79	        schema: [
80	            {
81	                type: "object",
82	                properties: { maxDistance: { type: "integer", minimum: 0 } },
83	                additionalProperties: false,
84	            },
85	        ],
86	        messages: {
87	            declaredTooEarly: "'{{name}}' is declared {{distance}} statements before its first use (max {{maxDistance}}); move it down",
88	        },
89	    },
90	    create(context) {
91	        const maxDistance = context.options[0]?.maxDistance ?? 5;
92	        const { sourceCode } = context;
93	        return {
94	            VariableDeclaration(node) {
95	                if (!isCandidate(node)) {
96	                    return;
97	                }
98	                const sites = usageSites(sourceCode, node);
99	                const [first] = sites;
100	                if (!first || first.nested || spansBranches(sites)) {
101	                    return;
102	                }
103	                const distance = statementDistance(node, first.statement);
104	                if (distance > maxDistance) {
105	                    context.report({
106	                        node,
107	                        messageId: "declaredTooEarly",
108	                        data: { name: first.name, distance, maxDistance },
109	                    });
110	                }
111	            },
112	        };
113	    },
114	};
